import { Cpu, Search, Sparkles } from "lucide-react";

import { OPEN_SMART_ADVISOR_EVENT } from "@/components/SmartPhoneAdvisor";
import type { ShopifyProduct } from "@/lib/shopify";
import { STORE_NAME } from "@/lib/storeConfig";

function openAdvisor(prompt: string) {
  window.dispatchEvent(
    new CustomEvent(OPEN_SMART_ADVISOR_EVENT, {
      detail: { prompt },
    }),
  );
}

/**
 * Product-page entry point for the global Smart Phone Advisor.
 * The legacy component name is kept to avoid changing the product route API.
 * Advice is now generated by NVIDIA AI and grounded in the live Space Call catalogue.
 */
export function GeminiShoppingAdvisor({
  product,
}: {
  product?: ShopifyProduct;
  catalog?: { products: ShopifyProduct[] };
}) {
  if (!product) return null;
  const title = product.node.title;

  return (
    <div className="overflow-hidden rounded-[1.5rem] border bg-card shadow-card">
      <div className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between sm:p-6">
        <div className="flex min-w-0 items-start gap-3">
          <span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-primary/10 text-primary">
            <Sparkles className="h-5 w-5" />
          </span>
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              <h2 className="text-base font-extrabold tracking-tight">Smart phone advisor</h2>
              <span className="inline-flex items-center gap-1 rounded-full border bg-background px-2 py-1 text-[9px] font-bold uppercase tracking-[0.12em] text-primary">
                <Cpu className="h-3 w-3" /> NVIDIA AI
              </span>
            </div>
            <p className="mt-1.5 max-w-2xl text-sm leading-relaxed text-muted-foreground">
              Compare {title}, understand its strengths and trade-offs, and match it against products currently available from {STORE_NAME}.
            </p>
          </div>
        </div>

        <button
          type="button"
          onClick={() =>
            openAdvisor(
              `Evaluate ${title}. Explain its important strengths and weaknesses, then tell me whether it fits a typical buyer and compare it with a strong alternative in the same class. Use ${STORE_NAME}'s live catalogue for store price and availability.`,
            )
          }
          className="inline-flex h-11 shrink-0 items-center justify-center gap-2 rounded-full bg-primary px-5 text-sm font-bold text-primary-foreground transition-transform hover:scale-[1.02]"
        >
          <Search className="h-4 w-4" /> Ask NVIDIA advisor
        </button>
      </div>

      <div className="grid border-t sm:grid-cols-3">
        {[
          {
            label: "Compare alternatives",
            prompt: `Compare ${title} with strong direct alternatives. Explain which option is better for camera, battery, display and performance, and use ${STORE_NAME}'s live catalogue for any store price or stock claim.`,
          },
          {
            label: "Camera & battery",
            prompt: `Evaluate ${title} for camera, battery, charging and display. Explain the practical strengths and trade-offs and avoid claiming live-web verification.`,
          },
          {
            label: "Best value in store",
            prompt: `Is ${title} good value compared with products currently in ${STORE_NAME}? Use the live store catalogue for prices and availability, then recommend the strongest option for the money.`,
          },
        ].map((action) => (
          <button
            key={action.label}
            type="button"
            onClick={() => openAdvisor(action.prompt)}
            className="border-b px-4 py-3 text-left text-xs font-bold transition-colors hover:bg-surface hover:text-primary sm:border-b-0 sm:border-r last:border-r-0"
          >
            {action.label}
          </button>
        ))}
      </div>
    </div>
  );
}
